UPDATE spu
SET view_cnt = view_cnt + 1
WHERE id = #{productId}

mapper.select:
SELECT s.id, s.title, s.intro as description, s.link as productUrl, s.status, s.create_time as createTime, s.update_time as updateTime, s.view_cnt as viewCount, s.cart_add_cnt as cartCount, sh.shop_name as shopName, sh.shop_avatar as shopAvatar, COALESCE(( SELECT COUNT(*) FROM user_collect uc WHERE uc.target_type = 'product' AND uc.target_id = CAST(s.id AS CHAR) ), 0) AS collectNumber FROM spu s LEFT JOIN shop sh ON s.user_id = sh.user_id WHERE 1=1
AND s.title LIKE CONCAT('%', #{title}, '%')
AND s.status = #{status}
AND s.user_id = #{userId}
AND sh.shop_name LIKE CONCAT('%', #{shopName}, '%')
ORDER BY s.create_time DESC LIMIT #{offset}, #{limit}

SELECT COUNT(*) FROM spu s LEFT JOIN shop sh ON s.user_id = sh.user_id WHERE 1=1
AND s.title LIKE CONCAT('%', #{title}, '%')
AND s.status = #{status}
AND s.user_id = #{userId}
AND sh.shop_name LIKE CONCAT('%', #{shopName}, '%')
